// ==========================================
// 1. MÁGICA: Tenta puxar do nome provável.
// SE O SEU NÓ TIVER OUTRO NOME, MUDE ABAIXO:
// ==========================================
const nomeDoNoDeLimpeza = "Code in JavaScript1";

const dadosOrganizados = $items(nomeDoNoDeLimpeza).map(i => i.json);

// ==========================================
// 2. Puxa o JSON bruto do Webhook
// ==========================================
const webhook = $('Webhook').first().json.body || $('Webhook').first().json;
const tripInfo = webhook.trip || {};

// ==========================================
// 3. Pega os resultados do OpenCage (coordenadas + endereço estruturado)
// ==========================================
const geocodeResults = $input.all();

// Função para extrair os componentes estruturados de endereço (NeighborHood/City/State/CEP)
// que agora são OBRIGATÓRIOS pela nova API
function extrairComponentes(item) {
    const result = item.json.results && item.json.results[0] ? item.json.results[0] : null;
    const geometry = result ? result.geometry : { lat: "", lng: "" };
    const components = result ? (result.components || {}) : {};

    return {
        lat: (geometry.lat || "").toString(),
        lng: (geometry.lng || "").toString(),
        neighborhood: components.neighbourhood || components.suburb || components.neighborhood || "",
        city: components.city || components.town || components.municipality || components.village || "",
        state: components.state_code || components.state || "",
        postal_code: components.postcode || ""
    };
}

let destInfo = { lat: "", lng: "", neighborhood: "", city: "", state: "", postal_code: "" };
const userInfo = {};

// ==========================================
// 4. Cruza as informações pela ordem
// (Item 0 = Destino, resto = Passageiros)
// ==========================================
geocodeResults.forEach((item, index) => {
    const info = extrairComponentes(item);

    if (index === 0) {
        destInfo = info;
    } else {
        const passageiroId = dadosOrganizados.filter(p => p.type === "passageiro")[index - 1]?.id;
        if (passageiroId) {
            userInfo[passageiroId] = info;
        }
    }
});

// ==========================================
// 5. Montagem do tempo (Pickup Time) - CORRIGIDO (PRIORIDADE NO SERVICETIME)
// ==========================================
let pickupTimeUnix = Math.floor(Date.now() / 1000);
try {
    if (tripInfo.scheduledDate) {

        // 1. Tenta achar primeiro o serviceTime do 1º passageiro
        let timeString = "";
        if (tripInfo.passengers && tripInfo.passengers.length > 0) {
            timeString = tripInfo.passengers[0].serviceTime;
        }

        // Se não achar, tenta o departureTime ou arrivalTime
        if (!timeString) {
            timeString = tripInfo.departureTime || tripInfo.arrivalTime || "00:00";
        }

        let [d, m, y] = tripInfo.scheduledDate.split('/');
        let [h, min] = timeString.split(':');

        // Se não veio o ano, usa o ano atual
        if (!y) {
            y = new Date().getFullYear().toString();
        } else if (y.length === 2) {
            y = "20" + y; // Converte 24 para 2024 (ou 26 para 2026)
        }

        // Função rápida para garantir 2 dígitos (ex: 8 vira "08")
        const pad = (num) => String(num).padStart(2, '0');

        // 2. O SEGREDO DO FUSO HORÁRIO: Forçamos o UTC-3 (Horário de Brasília)
        // Formato: "YYYY-MM-DDTHH:mm:00-03:00"
        const dataIsoBRT = `${y}-${pad(m)}-${pad(d)}T${pad(h || 0)}:${pad(min || 0)}:00-03:00`;

        const dateObj = new Date(dataIsoBRT);

        if (!isNaN(dateObj.getTime())) {
            pickupTimeUnix = Math.floor(dateObj.getTime() / 1000);
        }
    }
} catch (e) {
    console.log("Erro na data: ", e);
}

// ==========================================
// 6. Montagem dos Usuários Finais
// (COM O RE ADICIONADO DINAMICAMENTE)
// ==========================================
const finalUsers = dadosOrganizados.filter(p => p.type === "passageiro").map((u, index) => {
    const info = userInfo[u.id] || { lat: "", lng: "", neighborhood: "", city: "", state: "", postal_code: "" };

    // Busca o passageiro original no payload do Webhook pelo nome (ou pela posição como fallback)
    const passageiroOriginal = tripInfo.passengers?.find(p => p.name === u.name) || tripInfo.passengers?.[index] || {};

    return {
        id: u.id,
        sequence: (index * 2) + 1,
        name: u.name,
        phone: u.phone.replace(/\D/g, ""), // Remove formatação do telefone
        passenger_re: passageiroOriginal.re || "", // Puxando o RE dinamicamente
        passenger_cost_center: u.costCenter,
        pickup: {
            address: u.original_address,
            neighborhood: info.neighborhood,
            city: info.city,
            state: info.state,
            postal_code: info.postal_code,
            lat: info.lat,
            lng: info.lng
        }
    };
});

// ==========================================
// 7. Montagem dos Destinos Finais
// ==========================================
const finalDestinations = finalUsers.map((u, index) => {
    return {
        passengerId: u.id,
        sequence: (index * 2) + 2,
        location: {
            address: tripInfo.destinations?.[0]?.location?.address || "",
            neighborhood: destInfo.neighborhood,
            city: destInfo.city,
            state: destInfo.state,
            postal_code: destInfo.postal_code,
            reference: "",
            lat: destInfo.lat,
            lng: destInfo.lng
        }
    };
});

// ==========================================
// 8. RETORNO FINAL
// (Obrigatório para o n8n enviar para o próximo nó)
// ==========================================
return {
    partner: "322",
    user: tripInfo.company?.replace(/\D/g, "") || "CNPJ_VAZIO",
    password: "0104",
    request_id: `REQ-${Date.now()}`,
    pickup_time: pickupTimeUnix.toString(),
    distance: "0",
    stopped_time: "0",
    category: "taxi",
    passengers_no: finalUsers.length,
    send_sms: 1,
    suitcases_no: 0,
    requester_name: `${tripInfo.requester || ''}`,
    extra1: $('Webhook').first().json.body.trip.extra1,
    extra2: tripInfo.requester,
    payment_type: $('Webhook').first().json.body.trip.payment,
    users: finalUsers,
    destinations: finalDestinations
};

const payload = $input.first().json.body || $input.first().json;
const itemsToGeocode = [];

// ==========================================
// 1. FUNÇÃO "LIMPA-TRILHOS"
// ==========================================
function limparEndereco(endereco) {
    if (!endereco) return "";
    let limpo = endereco;
    limpo = limpo.replace(/^\d{8}[,\s-]+/, "");
    limpo = limpo.replace(/Cidade:/gi, "");
    limpo = limpo.replace(/UF:/gi, "");
    limpo = limpo.replace(/Estado:/gi, "");
    limpo = limpo.replace(/CEP:/gi, "");
    limpo = limpo.replace(/Bairro:/gi, "");
    limpo = limpo.replace(/RUA - /gi, "");
    limpo = limpo.replace(/AVENIDA - /gi, "");
    limpo = limpo.replace(/ - Número:\s*/gi, ", ");
    limpo = limpo.replace(/ - BAIRRO /gi, ", ");
    limpo = limpo.replace(/\s+/g, " ").trim();

    if (!limpo.toLowerCase().includes("brasil")) {
        limpo = limpo + ", Minas Gerais, Brasil";
    }
    return limpo.trim();
}

// O novo JSON guarda tudo dentro da caixa "trip"
const tripData = payload.trip || payload;

// ==========================================
// 2. ACHAR O DESTINO (Agora ele acha!)
// ==========================================
let destinoAddress = "";

if (tripData.destinations && tripData.destinations.length > 0 && tripData.destinations[0].location) {
    // Pega o endereço do novo formato
    destinoAddress = tripData.destinations[0].location.address;
} else if (tripData.destination) {
    // Pega se for o formato antigo
    destinoAddress = tripData.destination;
}

if (destinoAddress) {
    itemsToGeocode.push({
        type: "destino",
        id: 0,
        address: limparEndereco(destinoAddress),
        original_address: destinoAddress
    });
}

// ==========================================
// 3. ACHAR OS PASSAGEIROS E SALVAR OS DADOS
// ==========================================
// Vai direto na lista certa
const usersList = tripData.passengers || tripData.users || [];

if (usersList.length > 0) {
    usersList.forEach((u, index) => {
        // A nova API usa "pickup.address"
        const addressRaw = (u.pickup && u.pickup.address) ? u.pickup.address : u.address;

        itemsToGeocode.push({
            type: "passageiro",
            id: u.id || u.passengerId || String(index + 1),
            name: u.name || u.passengerName || ("Passageiro " + (index + 1)),
            phone: u.phone || u.passengerPhone || "",
            costCenter: u.costCenter || u.passenger_cost_center || u.cost_center || "",
            original_address: addressRaw, // Guarda o texto original
            address: limparEndereco(addressRaw) // Manda pro GPS o texto limpo
        });
    });
}

// Se não achar passageiros, devolve o erro formatado para o n8n
if (itemsToGeocode.length === 0 || (itemsToGeocode.length === 1 && itemsToGeocode[0].type === "destino")) {
    return [{
        json: {
            erro: "Falha ao encontrar a lista de passageiros. Verifique se o JSON tem a estrutura 'trip.passengers'.",
            payload: payload
        }
    }];
}

// Devolve tudo embrulhado no "json" para o n8n ficar feliz
return itemsToGeocode.map(item => ({ json: item }));

// Puxa o JSON bruto do Webhook
const webhook = $('Webhook').first().json.body || $('Webhook').first().json;
const trip = webhook.trip || {};
const passengers = trip.passengers || [];

// Pega a data e formata para DD-MM
const dataAgendamento = trip.scheduledDate || "data informada";
let dataFormatada = dataAgendamento;
if (dataAgendamento.includes('/')) {
    const partes = dataAgendamento.split('/');
    dataFormatada = `${partes[0]}-${partes[1]}`;
}

// Cria a lista de nomes formatada com bullet points para a mensagem
const listaNomes = passengers.map(p => `* ${p.name}`).join('\n');

const messages = [];

// Roda o loop para criar as mensagens individuais
passengers.forEach(p => {
    if (!p.phone) return;

    let foneString = p.phone.replace(/\D/g, "");
    if (foneString.length === 10 || foneString.length === 11) {
        foneString = "55" + foneString;
    }

    const horaAgendamento = p.serviceTime || trip.arrivalTime || "horário combinado";
    const nomeCompleto = p.name || "Passageiro";

    // Monta o template exatamente como você pediu
   const textoMsg = `Olá ${nomeCompleto}\n\nObrigado pelo contato! Sua corrida com a MINASTAXI esta agendada para o dia ${dataFormatada} às ${horaAgendamento}hs.\n\nPassageiros na mesma rota:\n${listaNomes}\n\n🔄 Atenção: Para clientes que utilizam rota compartilhada o horário informado refere-se ao início da rota, podendo haver pequenas variações no horário de embarque conforme a sequência dos atendimentos.\n\nPara falar com a atendente, o WhatsApp é 31 99537-6584.\n\nAtenciosamente;\nCentral de Atendimento`;

    messages.push({
        json: {
            number: foneString,
            text: textoMsg,
            delay: 1500
        }
    });
});

return messages;

// Puxa o JSON bruto lá do começo (Webhook)
const webhook = $('Webhook').first().json.body || $('Webhook').first().json;
const trip = webhook.trip || {};
const passengers = trip.passengers || [];

const dataAgendamento = trip.scheduledDate || "data informada";

// Busca o horário de ida (priorizando o serviceTime do primeiro passageiro)
const horaIda = (passengers.length > 0 && passengers[0].serviceTime)
    ? passengers[0].serviceTime
    : (trip.arrivalTime || trip.departureTime || "Não informado");

// Busca o horário de retorno (com aviso caso venha vazio)
const horaVolta = trip.returnTime || trip.horario_retorno || "Sem retorno agendado";

// Monta uma lista com o nome de quem vai no táxi para o gestor saber
const listaNomes = passengers.map(p => `• ${p.name}`).join("\n");

// Monta o texto do relatório para o gestor com o espaçamento correto (\n)
const textoMsg = `📊 *Relatório de Agendamentos* 🚕\n\nNovos táxis foram solicitados para o dia *${dataAgendamento}*.\n\n🕐 *Horário de Ida:* ${horaIda}\n🕢 *Horário de Retorno:* ${horaVolta}\n\n*Passageiros da corrida:*\n${listaNomes}`;

// ==========================================
// ATENÇÃO: COLOQUE OS NÚMEROS DOS GESTORES AQUI
// Lembre-se de colocar o 55 e o DDD
// ==========================================
const numerosGestores = [
    "5531985628956", // Gestor 1
    "5531999999926"  // Gestor 2
];

const messages = [];

// Cria um envio para cada gestor
numerosGestores.forEach(numero => {
    messages.push({
        json: {
            number: numero.trim(), // O .trim() garante que espaços acidentais não quebrem o envio
            text: textoMsg
        }
    });
});

return messages;

// ==========================================
// 1. Puxa o JSON bruto do Webhook
// ==========================================
const webhook = $('Webhook').first().json.body || $('Webhook').first().json;
const tripInfo = webhook.trip || {};

// ==========================================
// 2. TRAVA DE SEGURANÇA (O IF MÁGICO)
// ==========================================
// Verifica se existe horário de volta. Se não existir, cancela a criação da volta.
const timeString = tripInfo.returnTime || tripInfo.horario_retorno || "";

// Se a string estiver vazia, for null, ou for "00:00" (dependendo de como seu sistema manda)
if (!timeString || timeString.trim() === "" || timeString === "00:00") {
    console.log("Corrida sem horário de volta. Abortando a criação da rota de volta.");
    return []; // Retornar array vazio faz o n8n parar este galho do fluxo aqui.
}

// ==========================================
// 3. Puxa os dados organizados do início
// ==========================================
const nomeDoNoDeLimpeza = "Code in JavaScript1";
const dadosOrganizados = $items(nomeDoNoDeLimpeza).map(i => i.json);

// ==========================================
// 4. Pega os resultados do OpenCage EXPLÍCITO
// ==========================================
const geocodeResults = $items("HTTP Request").map(i => i.json);

// Função para extrair os componentes estruturados de endereço (NeighborHood/City/State/CEP)
// que agora são OBRIGATÓRIOS pela nova API
function extrairComponentes(geoResult) {
    const result = geoResult.results && geoResult.results[0] ? geoResult.results[0] : null;
    const geometry = result ? result.geometry : { lat: "", lng: "" };
    const components = result ? (result.components || {}) : {};

    return {
        lat: (geometry.lat || "").toString(),
        lng: (geometry.lng || "").toString(),
        neighborhood: components.neighbourhood || components.suburb || components.neighborhood || "",
        city: components.city || components.town || components.municipality || components.village || "",
        state: components.state_code || components.state || "",
        postal_code: components.postcode || ""
    };
}

let destInfo = { lat: "", lng: "", neighborhood: "", city: "", state: "", postal_code: "" };
const userInfo = {};

geocodeResults.forEach((geoResult, index) => {
    const info = extrairComponentes(geoResult);

    if (index === 0) {
        // O índice 0 no OpenCage foi o endereço da empresa (origem da volta)
        destInfo = info;
    } else {
        const passageiroId = dadosOrganizados.filter(p => p.type === "passageiro")[index - 1]?.id;
        if (passageiroId) {
            userInfo[passageiroId] = info;
        }
    }
});

// ==========================================
// 5. Montagem do tempo (Focado no Horário de Retorno)
// ==========================================
let pickupTimeUnix = Math.floor(Date.now() / 1000);
try {
    if (tripInfo.scheduledDate) {
        let [d, m, y] = tripInfo.scheduledDate.split('/');
        let [h, min] = timeString.split(':');

        if (!y) y = new Date().getFullYear().toString();
        else if (y.length === 2) y = "20" + y;

        const pad = (num) => String(num).padStart(2, '0');
        const dataIsoBRT = `${y}-${pad(m)}-${pad(d)}T${pad(h || 0)}:${pad(min || 0)}:00-03:00`;

        const dateObj = new Date(dataIsoBRT);
        if (!isNaN(dateObj.getTime())) {
            pickupTimeUnix = Math.floor(dateObj.getTime() / 1000);
        }
    }
} catch (e) {
    console.log("Erro na data de volta: ", e);
}

// ==========================================
// 6. INVERSÃO DOS PASSAGEIROS E ROTAS
// ==========================================
const passageirosIda = dadosOrganizados.filter(p => p.type === "passageiro");
// O .reverse() transforma P1, P2, P3 em P3, P2, P1
const passageirosVolta = [...passageirosIda].reverse();

const finalUsers = passageirosVolta.map((u, index) => {
    const original = tripInfo.passengers?.find(p => p.name === u.name) || {};
    return {
        id: u.id,
        sequence: (index * 2) + 1,
        name: u.name,
        phone: u.phone.replace(/\D/g, ""),
        passenger_re: original.re || "",
        passenger_cost_center: u.costCenter,
        // Na VOLTA, o passageiro embarca (pickup) na EMPRESA
        pickup: {
            address: tripInfo.destinations?.[0]?.location?.address || "",
            neighborhood: destInfo.neighborhood,
            city: destInfo.city,
            state: destInfo.state,
            postal_code: destInfo.postal_code,
            lat: destInfo.lat,
            lng: destInfo.lng
        }
    };
});

const finalDestinations = passageirosVolta.map((u, index) => {
    const info = userInfo[u.id] || { lat: "", lng: "", neighborhood: "", city: "", state: "", postal_code: "" };
    return {
        passengerId: u.id,
        sequence: (index * 2) + 2,
        // Na VOLTA, o passageiro desce (location) em CASA
        location: {
            address: u.original_address,
            neighborhood: info.neighborhood,
            city: info.city,
            state: info.state,
            postal_code: info.postal_code,
            reference: "",
            lat: info.lat,
            lng: info.lng
        }
    };
});

// ==========================================
// 7. RETORNO FINAL DA VOLTA
// ==========================================
return {
    partner: "322",
    user: tripInfo.company?.replace(/\D/g, "") || "CNPJ_VAZIO",
    password: "0104",
    request_id: `REQ-VOLTA-${Date.now()}`,
    pickup_time: pickupTimeUnix.toString(),
    distance: "0",
    stopped_time: "0",
    category: "taxi",
    passengers_no: finalUsers.length,
    send_sms: 1,
    suitcases_no: 0,
    requester_name: `${tripInfo.requester || ''}`,
    extra1: $('Webhook').first().json.body.trip.extra1,
    extra2: tripInfo.requester,
    payment_type: $('Webhook').first().json.body.trip.payment,
    users: finalUsers,
    destinations: finalDestinations,
    tipo_rota: "VOLTA"
};
